# region: emit
def emit(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: shape
def shape(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: intake
def intake(xs, offset=4):
    return [v + offset for v in xs[1:]]

# region: render
def render(xs, cut=3):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: sift
def sift(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return sift(render(intake(shape(emit(raw)))))

